                    if (all(grid[r1][c] == color and grid[r2][c] == color
                            for c in range(c1, c2 + 1))
                        and all(grid[r][c1] == color and grid[r][c2] == color
                                for r in range(r1, r2 + 1))
                        and all(grid[r][c] == bg
                                for r in range(r1 + 1, r2)
                                for c in range(c1 + 1, c2))):
